/// <summary>
/// MetPurchLineCancelBusinessEvent added for Purchase Order Line Cancellation Business Event
/// Bug 311185
/// </summary>
[BusinessEvents(classStr(MetPurchLineCancelBusinessEventContract), 
    '@MET:POCancellationBusinessEvent', 
    '@MET:POBusinessEventDesc', 
     ModuleAxapta::AccountsPayable)]
public class MetPurchLineCancelBusinessEvent extends BusinessEventsBase
{
    private MetPurchLineCancelBusinessEventContract contract;

}

Method.Source:
public static MetPurchLineCancelBusinessEvent newFromPurchTable(PurchTable _purchTable)
{
    MetPurchLineCancelBusinessEvent businessEvent = new MetPurchLineCancelBusinessEvent();
    MetPurchLineCancelBusinessEventContract contract = new MetPurchLineCancelBusinessEventContract();

    contract.parmPurchId(_purchTable.PurchId);
    contract.parmLegalEntity(_purchTable.DataAreaId);

    businessEvent.newFromContract(contract);
    return businessEvent;
}

[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return contract;
}
